<style>
    :root{font-family:Inter,Arial,sans-serif;color:#172b3b;background:#f4f7fb;color-scheme:light}*{box-sizing:border-box}body{margin:0}a{color:#2563eb;text-decoration:none}
    .site-header{background:#123b5d;color:#fff}.top,main,.site-footer{width:min(1180px,calc(100% - 36px));margin:0 auto}.top{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{color:#fff;font-size:1.08rem;font-weight:800;letter-spacing:-.02em}.top nav{display:flex;align-items:center;gap:18px}.top nav a{color:#fff;font-size:.9rem;font-weight:600}.top nav form{margin:0}
    main{padding:34px 0 58px}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:24px}.eyebrow{color:#2563eb;font-size:.76rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.page-heading h1{margin:7px 0;color:#123b5d;font-size:clamp(1.9rem,4vw,2.7rem);letter-spacing:-.04em}.page-heading p,.muted{margin:0;color:#667788;line-height:1.65}.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:43px;padding:0 16px;border:1px solid transparent;border-radius:9px;background:#2563eb;color:#fff;font:inherit;font-weight:700;cursor:pointer;transition:background .18s ease,transform .18s ease,box-shadow .18s ease}.button:hover{background:#1d4ed8;box-shadow:0 8px 18px #2563eb22;transform:translateY(-1px)}.button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #60a5fa;outline-offset:3px}.button.secondary{background:#e8eef5;color:#123b5d}.button.secondary:hover{background:#dce7f1}.button:disabled{opacity:.65;cursor:wait;transform:none}.button:disabled::before{content:"";width:14px;height:14px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:spin .7s linear infinite}
    .notice{margin:14px 0;padding:13px 16px;border-radius:10px;background:#ecfdf3;color:#067647;line-height:1.55}.notice.error{background:#fff0ef;color:#b42318}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;align-items:start;gap:22px}.panel{padding:24px;border:1px solid #e3eaf1;border-radius:15px;background:#fff;box-shadow:0 8px 24px #123b5d08}.panel h2{margin:0 0 8px;color:#123b5d;font-size:1.12rem}.panel-intro{margin:0 0 20px;color:#667788;line-height:1.6}.progress{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:0 0 20px;padding:0;list-style:none}.progress li{display:grid;justify-items:center;gap:7px;color:#7a8998;text-align:center;font-size:.75rem;font-weight:700}.progress-mark{display:grid;width:32px;height:32px;place-items:center;border:1px solid #cbd6e1;border-radius:50%;background:#fff;color:#667788}.progress li.is-active{color:#123b5d}.progress li.is-active .progress-mark{border-color:#2563eb;background:#2563eb;color:#fff;box-shadow:0 5px 13px #2563eb36}.progress li.is-complete .progress-mark{border-color:#a6e2bf;background:#ecfdf3;color:#067647}
    .wizard-step{padding:0;border:0;margin:0}.wizard-step[hidden]{display:none}.wizard-step legend{width:100%;margin:0 0 18px;padding:0;color:#123b5d;font-size:1.25rem;font-weight:800}.choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.choice-card{display:flex;align-items:flex-start;gap:13px;min-height:126px;padding:17px;border:1px solid #dce5ee;border-radius:12px;background:#fff;cursor:pointer;transition:border-color .18s ease,background .18s ease,box-shadow .18s ease}.choice-card:hover{border-color:#8bb5ef}.choice-card.is-selected{border-color:#2563eb;background:#f4f8ff;box-shadow:0 0 0 2px #2563eb12}.choice-card input{width:18px;height:18px;margin:3px 0 0;accent-color:#2563eb;flex:0 0 auto}.choice-card strong{display:block;color:#123b5d}.choice-card small{display:block;margin-top:7px;color:#667788;font-size:.86rem;line-height:1.55}
    .vehicle-list{display:grid;gap:10px}.vehicle-choice{display:flex;align-items:center;gap:13px;padding:15px;border:1px solid #dce5ee;border-radius:11px;cursor:pointer}.vehicle-choice:hover,.vehicle-choice.is-selected{border-color:#2563eb;background:#f4f8ff}.vehicle-choice input{width:18px;height:18px;accent-color:#2563eb}.vehicle-copy{display:grid;gap:4px}.vehicle-copy strong{color:#123b5d}.vehicle-copy span{color:#667788;font-size:.87rem}.plate{display:inline-block;padding:3px 8px;border:1px solid #cbd6e1;border-radius:6px;color:#34495e;font-size:.78rem;font-weight:800;letter-spacing:.05em}
    .service-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.service-card{position:relative;display:grid;grid-template-columns:72px minmax(0,1fr);gap:13px;min-height:118px;padding:13px;border:1px solid #dce5ee;border-radius:12px;cursor:pointer;transition:border-color .18s ease,background .18s ease,box-shadow .18s ease}.service-card:hover{border-color:#8bb5ef}.service-card.is-selected{border-color:#2563eb;background:#f4f8ff;box-shadow:0 0 0 2px #2563eb12}.service-card input{position:absolute;top:14px;right:14px;width:18px;height:18px;accent-color:#2563eb}.service-image{width:72px;height:72px;align-self:start;border-radius:9px;background:#edf3f8;object-fit:cover}.service-placeholder{display:grid;place-items:center;color:#2563eb;font-size:1.5rem}.service-copy{padding-right:21px}.service-copy strong{display:block;color:#123b5d}.service-copy p{margin:5px 0 8px;color:#667788;font-size:.83rem;line-height:1.45}.service-meta{display:flex;flex-wrap:wrap;gap:8px 13px;color:#53687b;font-size:.78rem}.empty-state{padding:20px;border:1px dashed #bdcbd9;border-radius:11px;background:#f9fbfd;color:#53687b;line-height:1.6}.empty-state strong{color:#123b5d}.empty-state p{margin:5px 0 0}
    .field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.field{display:grid;gap:7px}.field.full{grid-column:1/-1}.field label{color:#29445b;font-size:.9rem;font-weight:700}.field input,.field select,.field textarea{width:100%;min-height:44px;padding:10px 12px;border:1px solid #cbd6e1;border-radius:8px;background:#fff;color:#172b3b;font:inherit}.field textarea{min-height:105px;resize:vertical;line-height:1.5}.field-error{margin:0;color:#b42318;font-size:.83rem;line-height:1.45}.hint{margin:8px 0 0;color:#667788;font-size:.83rem;line-height:1.55}.contact-card{display:grid;gap:11px;padding:16px;border-radius:11px;background:#f4f7fb}.contact-card div{display:grid;gap:3px}.contact-card span{color:#667788;font-size:.82rem}.contact-card strong{color:#123b5d;font-size:.9rem}.contact-card a{justify-self:start;font-size:.86rem;font-weight:700}
    .summary-list{display:grid;gap:0;margin:0}.summary-row{display:grid;grid-template-columns:150px minmax(0,1fr);gap:14px;padding:13px 0;border-bottom:1px solid #edf1f5}.summary-row:last-child{border-bottom:0}.summary-row dt{color:#667788;font-size:.87rem}.summary-row dd{margin:0;color:#253f55;line-height:1.55;overflow-wrap:anywhere}.summary-total{margin-top:14px;padding-top:14px;border-top:1px solid #dce5ee;color:#123b5d;font-weight:800}.summary-total span{float:right}.summary-note{margin-top:13px;padding:12px;border-radius:9px;background:#f4f7fb;color:#53687b;font-size:.84rem;line-height:1.55}
    .form-actions{display:flex;justify-content:space-between;gap:10px;margin-top:24px;padding-top:18px;border-top:1px solid #edf1f5}.form-actions-end{justify-content:flex-end}.aside{position:sticky;top:20px}.aside .panel{padding:20px}.aside h2{margin-bottom:13px}.aside .summary-row{grid-template-columns:1fr;gap:4px;padding:10px 0}.aside .summary-row dd{font-size:.88rem}.site-footer{padding:19px 0 27px;border-top:1px solid #e3eaf1;color:#748395;font-size:.84rem}.list-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.appointment-card{padding:20px;border:1px solid #e3eaf1;border-radius:13px;background:#fff;box-shadow:0 7px 22px #123b5d07}.appointment-card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.appointment-card h2{margin:0;color:#123b5d;font-size:1rem}.appointment-card p{margin:9px 0 0;color:#667788;line-height:1.5}.status{display:inline-flex;padding:5px 9px;border-radius:999px;background:#fff7e6;color:#9a6700;font-size:.75rem;font-weight:800;white-space:nowrap}.status.confirmed,.status.completed{background:#ecfdf3;color:#067647}.status.rejected,.status.cancelled{background:#fff0ef;color:#b42318}.card-link{display:inline-flex;margin-top:15px;font-weight:700}
    @keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){.layout{grid-template-columns:1fr}.aside{position:static}.service-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
    @media(max-width:640px){.top{align-items:flex-start;flex-direction:column;padding:14px 0}.top nav{flex-wrap:wrap;gap:12px}.page-heading{align-items:flex-start;flex-direction:column}.page-heading>.button{width:100%}.panel{padding:18px}.progress{grid-template-columns:repeat(3,1fr);row-gap:13px}.progress li{font-size:.7rem}.choice-grid,.service-grid,.list-grid,.field-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.summary-row{grid-template-columns:1fr;gap:4px}.form-actions{flex-wrap:wrap}.form-actions .button{flex:1}.service-card{grid-template-columns:62px minmax(0,1fr)}.service-image{width:62px;height:62px}}
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition-duration:.01ms!important;animation-duration:.01ms!important}}
</style>
